require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/orphaned_queue_job.json
# is QueueExecution.orphaned over every combination of the five SolidQueue
# execution flags and the job's age, generated by
# `lake exe syrus_fixtures orphaned_queue_job`. This runs the real
# WorkEngine::Reconciler#orphaned_queue_job? on the same inputs. A job is
# orphaned, and safe to delete and re-enqueue, exactly when it carries no
# execution row at all and is past the grace. The test database has no SolidQueue tables,
# so the snapshot that produces the flags is not part of this check.
RSpec.describe "QueueExecution model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/orphaned_queue_job.json").read)
  flags = %w[ready claimed scheduled blocked failed]
  let(:reconciler) { WorkEngine::Reconciler.new(source: "conformance") }

  it "covers every combination of the execution flags" do
    expect(fixture.fetch("cases").size).to eq(2**(flags.size + 1))
  end

  fixture.fetch("cases").each do |example|
    set = flags.select { |flag| example.fetch(flag) }

    age = example.fetch("old") ? "an old" : "a new"
    it "calls #{age} job with #{set.empty? ? 'no execution row' : set.join(' and ')} #{example.fetch('orphaned') ? 'orphaned' : 'not orphaned'}" do
      changed_at = example.fetch("old") ? 1.hour.ago : 10.seconds.ago
      snapshot = flags.to_h { |flag| [ flag.to_sym, example.fetch(flag) ] }.merge(created_at: changed_at, updated_at: changed_at)

      expect(reconciler.send(:orphaned_queue_job?, snapshot)).to eq(example.fetch("orphaned"))
    end
  end
end
